#!/usr/bin/env node
/**
 * fix-favicon.mjs   (website ke folder mein)
 *
 * Google search mein ghar wale nishan ki jagah asli logo dikhane ke liye.
 *
 *   1. Saat naye icons src/assets/uploads/brand/ mein rakhta hai (yeh script
 *      ke andar hi band hain — alag se kuch copy nahi karna). Sab asli logo
 *      ke daire wale nishan se bane hain, neeli chaukor zameen par, likhai
 *      ke baghair (16-32px par likhai parhi nahi jati).
 *
 *   2. site.json mein "favicon" ko naye 96px PNG par karta hai. <head> wali
 *      line pehle se {{ site.favicon }} istemal karti hai, to CMS ka favicon
 *      wala khana bhi kaam karta rahega.
 *
 *   3. <head> mein favicon.ico aur apple-touch-icon ki do lines jorta hai.
 *
 *   4. manifest ke icons theek karta hai — abhi woh PNG ko "image/svg+xml"
 *      aur "sizes: any" bata raha hai, aur "maskable" ki wajah se Android
 *      logo ke kinare kaat deta.
 *
 * Purani favicon.png ko HAATH NAHI lagata.
 *
 * SAB YA KUCH BHI NAHI. Backup: .bakfav
 *
 *   node tools/fix-favicon.mjs            <- sirf dikhata hai
 *   node tools/fix-favicon.mjs --write    <- likhta hai
 */

import fs from 'node:fs';
import path from 'node:path';

const ROOT = process.cwd();
const WRITE = process.argv.includes('--write');
const out = [];
const say = (s = '') => { out.push(s); console.log(s); };
const fails = [];
const fail = (m, d) => { fails.push(m); if (d) fails.push('        ' + d); };
const rel = (f) => path.relative(ROOT, f).split(path.sep).join('/');

const BRAND_URL = '/assets/uploads/brand';
const BRAND_DIR = path.join(ROOT, 'src', 'assets', 'uploads', 'brand');
const NEW_FAVICON = BRAND_URL + '/favicon-96.png';

/* ---------- tasweerein (base64) ---------- */
const ICONS = {
"favicon.ico": "",
"favicon-48.png": "",
"favicon-96.png": "",
"apple-touch-icon.png": "",
"icon-192.png": "",
"icon-512.png": "",
"icon-maskable-512.png": ""
};

/* ---------- files ---------- */
const files = new Map();
const load = (relp) => {
  if (files.has(relp)) return files.get(relp);
  const abs = path.join(ROOT, relp.split('/').join(path.sep));
  if (!fs.existsSync(abs)) return null;
  const orig = fs.readFileSync(abs, 'utf8');
  const hadCRLF = orig.includes('\r\n');
  const f = { abs, orig, origLF: hadCRLF ? orig.replace(/\r\n/g, '\n') : orig, hadCRLF, changed: false };
  f.text = f.origLF;
  files.set(relp, f);
  return f;
};

say('');
say('FAVICON PATCH' + (WRITE ? '   (LIKH RAHA HOON)' : '   (SIRF DIKHA RAHA HOON)'));
say('='.repeat(78));

/* ==================================================================== */
say('');
say('1. NAYE ICONS  ->  src/assets/uploads/brand/');
say('-'.repeat(78));
if (!fs.existsSync(BRAND_DIR)) fail('XX  src/assets/uploads/brand/ nahi mila');
const toWriteImgs = [];
for (const [name, b64] of Object.entries(ICONS)) {
  const buf = Buffer.from(b64, 'base64');
  const dest = path.join(BRAND_DIR, name);
  let note = 'naya';
  if (fs.existsSync(dest)) {
    const same = fs.readFileSync(dest).equals(buf);
    note = same ? 'pehle se wahi hai' : 'MOJOOD HAI — alag file';
    if (!same) fail('XX  ' + rel(dest) + ' pehle se mojood hai aur alag hai — us par likhna nahi chahta');
  }
  /* PNG / ICO ki pehchan */
  const isPng = buf.slice(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]));
  const isIco = buf[0] === 0 && buf[1] === 0 && buf[2] === 1 && buf[3] === 0;
  if (!(name.endsWith('.png') ? isPng : isIco)) fail('XX  ' + name + ' ka andar ka matan theek nahi');
  let dim = '';
  if (isPng) dim = buf.readUInt32BE(16) + 'x' + buf.readUInt32BE(20);
  if (isIco) dim = buf.readUInt16LE(4) + ' naap (16/32/48)';
  say('   ' + name.padEnd(24) + String(buf.length).padStart(7) + ' bytes   ' + dim.padEnd(18) + note);
  if (note === 'naya') toWriteImgs.push([dest, buf]);
}

/* ==================================================================== */
say('');
say('2. src/_data/site.json  —  "favicon"');
say('-'.repeat(78));
const SJ = 'src/_data/site.json';
const sj = load(SJ);
if (!sj) fail('XX  ' + SJ + ' nahi mili');
else {
  const re = /("favicon"\s*:\s*")([^"]*)(")/g;
  const hits = [...sj.text.matchAll(re)];
  if (hits.length !== 1) fail('XX  site.json mein "favicon" ' + hits.length + ' jagah mila, 1 chahiye tha');
  else {
    const old = hits[0][2];
    say('   abhi:  ' + old);
    if (old === NEW_FAVICON) say('   --  pehle se naya hai');
    else {
      sj.text = sj.text.replace(re, '$1' + NEW_FAVICON + '$3');
      sj.changed = true;
      say('   naya:  ' + NEW_FAVICON);
    }
  }
}

/* ==================================================================== */
say('');
say('3. <head> MEIN ICON KI LINES');
say('-'.repeat(78));
const incDirs = [path.join(ROOT, 'src', '_includes'), path.join(ROOT, 'src', '_layouts')];
const iconHits = [];
const walk = (d) => {
  if (!fs.existsSync(d)) return;
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    if (/\.bak/.test(e.name)) continue;
    const f = path.join(d, e.name);
    if (e.isDirectory()) { walk(f); continue; }
    if (!/\.njk$/.test(e.name)) continue;
    const t = fs.readFileSync(f, 'utf8').replace(/\r\n/g, '\n');
    t.split('\n').forEach((l, i) => { if (/<link[^>]*rel=["'](shortcut )?icon["']/i.test(l)) iconHits.push([rel(f), i, l]); });
  }
};
incDirs.forEach(walk);
for (const [f, i, l] of iconHits) say('   ' + f + ':' + (i + 1) + '   ' + l.trim().slice(0, 110));

let head = null;
if (iconHits.length !== 1) fail('XX  rel="icon" wali line ' + iconHits.length + ' jagah mili, 1 chahiye thi');
else {
  const [f, i, l] = iconHits[0];
  if (!/site\.favicon/.test(l)) say('   !!  is line mein site.favicon nahi — CMS ka khana is par asar nahi karega');
  head = load(f);
  const lines = head.text.split('\n');
  if (head.text.includes('apple-touch-icon') || head.text.includes('favicon.ico')) {
    say('   --  apple-touch-icon / favicon.ico pehle se mojood hain');
  } else {
    const indent = (l.match(/^\s*/) || [''])[0];
    lines.splice(i + 1, 0,
      indent + '<link rel="icon" href="' + BRAND_URL + '/favicon.ico" sizes="48x48">',
      indent + '<link rel="apple-touch-icon" href="' + BRAND_URL + '/apple-touch-icon.png">');
    head.text = lines.join('\n');
    head.changed = true;
    say('   OK  do lines jori: favicon.ico aur apple-touch-icon');
  }
}

/* ==================================================================== */
say('');
say('4. MANIFEST KE ICONS');
say('-'.repeat(78));
const MF = 'src/manifest.webmanifest.njk';
const mf = load(MF);
if (!mf) fail('XX  ' + MF + ' nahi mili');
else {
  const m = mf.text.match(/("icons"\s*:\s*)\[[\s\S]*?\]/);
  if (!m) fail('XX  manifest mein "icons" ki fehrist nahi mili');
  else {
    say('   abhi:');
    m[0].split('\n').forEach((l) => say('      ' + l.slice(0, 100)));
    const icons = [
      { src: BRAND_URL + '/icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any' },
      { src: BRAND_URL + '/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any' },
      { src: BRAND_URL + '/icon-maskable-512.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
    ];
    const indent = (mf.text.slice(0, mf.text.indexOf(m[0])).match(/\n([ \t]*)$/) || [, '  '])[1];
    const oneLine = !m[0].includes('\n');
    const arr = oneLine ? JSON.stringify(icons)
      : JSON.stringify(icons, null, 2).split('\n').map((l, k) => (k === 0 ? l : indent + l)).join('\n');
    mf.text = mf.text.replace(m[0], m[1] + arr);
    mf.changed = mf.text !== mf.origLF;
    say(mf.changed ? '   naya: 192, 512 aur ek alag maskable — sab image/png' : '   --  pehle se theek hai');
  }
}

/* ==================================================================== */
say('');
say('5. KYA GOOGLE IN TAK POHANCH SAKTA HAI?');
say('-'.repeat(78));
const rb = path.join(ROOT, '_site', 'robots.txt');
if (!fs.existsSync(rb)) say('   --  _site/robots.txt nahi — build ke baad dobara dekh lein');
else {
  const t = fs.readFileSync(rb, 'utf8');
  /* groups */
  const groups = []; let cur = null;
  for (const raw of t.split(/\r?\n/)) {
    const l = raw.replace(/#.*/, '').trim(); if (!l) { cur = null; continue; }
    const [k, ...v] = l.split(':'); const val = v.join(':').trim();
    if (/^user-agent$/i.test(k)) { if (!cur || cur.rules.length) { cur = { agents: [], rules: [] }; groups.push(cur); } cur.agents.push(val.toLowerCase()); }
    else if (cur && /^(dis)?allow$/i.test(k)) cur.rules.push([k.toLowerCase(), val]);
  }
  const blocks = (agent, p) => {
    const g = groups.find((x) => x.agents.includes(agent)) || groups.find((x) => x.agents.includes('*'));
    if (!g) return false;
    let best = null;
    for (const [k, v] of g.rules) if (v && p.startsWith(v) && (!best || v.length > best[1].length)) best = [k, v];
    return best ? best[0] === 'disallow' : false;
  };
  for (const a of ['googlebot', 'googlebot-image']) {
    for (const p of ['/', BRAND_URL + '/favicon-96.png']) {
      const b = blocks(a, p);
      say('   ' + a.padEnd(16) + p.padEnd(44) + (b ? 'XX ROKA HUA' : 'OK'));
      if (b) fail('XX  robots.txt ' + a + ' ko ' + p + ' se rokta hai');
    }
  }
}

/* ==================================================================== */
say('');
say('JAANCH');
say('-'.repeat(78));
const check = (ok, label) => { say('   ' + (ok ? 'OK  ' : 'XX  ') + label); if (!ok) fail('XX  jaanch nakaam: ' + label); };
if (sj && sj.changed) {
  let ok = true; try { JSON.parse(sj.text); } catch { ok = false; }
  check(ok, 'site.json abhi bhi sahi JSON hai');
  check(sj.text.split('\n').length === sj.origLF.split('\n').length, 'site.json ki lines ki ginti waisi hi');
  const blank = (s) => s.replace(/("favicon"\s*:\s*")[^"]*"/, '$1"');
  check(blank(sj.text) === blank(sj.origLF), 'favicon ki qeemat ke ilawa site.json mein ek harf nahi badla');
}
if (head && head.changed) {
  check(head.text.split('\n').length === head.origLF.split('\n').length + 2, '<head> mein sirf do lines barhin');
  check((head.text.match(/rel=["']icon["']/g) || []).length === 2, 'ab do rel="icon" lines hain (png + ico)');
}
if (mf && mf.changed) {
  /* {{ }} string ke andar ho to x, bahar ho (jaise `| json`) to "x" */
  const fill = (s) => {
    let o = '', inStr = false;
    for (let i = 0; i < s.length; i++) {
      if (s.startsWith('{{', i)) { const j = s.indexOf('}}', i); o += inStr ? 'x' : '"x"'; i = j + 1; continue; }
      if (s.startsWith('{%', i)) { const j = s.indexOf('%}', i); i = j + 1; continue; }
      const c = s[i];
      if (c === '"' && s[i - 1] !== '\\') inStr = !inStr;
      o += c;
    }
    return o;
  };
  const probe = fill(mf.text.replace(/^---[\s\S]*?---/, ''));
  let ok = true; try { JSON.parse(probe); } catch { ok = false; }
  check(ok, 'manifest JSON ki shakal sahi hai');
  check(!/svg\+xml/.test(mf.text), 'manifest mein ghalat svg type nahi raha');
}

/* ==================================================================== */
say('');
say('='.repeat(78));
if (fails.length) {
  say('');
  say('   RUK GAYA — KUCH BHI NAHI BADLA');
  say('');
  for (const f of fails) say('   ' + f);
  say('');
  fs.writeFileSync(path.join(ROOT, '_favicon.txt'), out.join('\n') + '\n', 'utf8');
  console.log('-'.repeat(78));
  console.log('LIKHA: _favicon.txt');
  process.exit(1);
}

if (!WRITE) {
  say('');
  say('   Sab jaanch saaf. Abhi kuch likha NAHI.');
  say('   Lagane ke liye:   node tools/fix-favicon.mjs --write');
  say('');
} else {
  say('');
  for (const [dest, buf] of toWriteImgs) { fs.writeFileSync(dest, buf); say('   LIKHA: ' + rel(dest)); }
  for (const [r, f] of files) {
    if (!f.changed) continue;
    fs.copyFileSync(f.abs, f.abs + '.bakfav');
    fs.writeFileSync(f.abs, f.hadCRLF ? f.text.replace(/\n/g, '\r\n') : f.text, 'utf8');
    say('   LIKHA: ' + r + '   (backup: ' + path.basename(f.abs) + '.bakfav)');
  }
  say('');
  say('   Ab:   npm run build');
  say('');
}
fs.writeFileSync(path.join(ROOT, '_favicon.txt'), out.join('\n') + '\n', 'utf8');
console.log('-'.repeat(78));
console.log('LIKHA: _favicon.txt');
